### What is the happy path for login?

The happy path is a single case: valid username and valid password lead to a successful login and a redirect to the dashboard. Everything interesting is around it.

```typescript
// tests/login/happy-path.spec.ts
import { test, expect } from '@playwright/test';

test('Valid credentials redirect to dashboard', async ({ page }) => {
  await page.goto('/login');
  await page.getByLabel('Username').fill(process.env.TEST_USER!);
  await page.getByLabel('Password').fill(process.env.TEST_PASS!);
  await page.getByRole('button', { name: 'Sign In' }).click();

  await expect(page).toHaveURL(/\/dashboard/);
  await expect(page.getByRole('heading', { name: 'Welcome' })).toBeVisible();
  await expect(page.getByText('Account Balance')).toBeVisible();
});
```

### What negative credential cases should you test?

The negative credential matrix covers valid username with invalid password, invalid username with any password, both invalid, and the critical rule that all failures return the same generic message so an attacker cannot tell which part was wrong.

```typescript
// tests/login/negative-credentials.spec.ts
const negativeCases = [
  { user: 'rajesh@nationalbank.in', pass: 'wrong', desc: 'valid user, wrong pass' },
  { user: 'nobody@nationalbank.in', pass: 'any', desc: 'unknown user' },
  { user: 'nobody@nationalbank.in', pass: 'wrong', desc: 'both invalid' },
  { user: '', pass: '', desc: 'both empty' },
  { user: '   ', pass: '   ', desc: 'whitespace only' },
];

for (const { user, pass, desc } of negativeCases) {
  test(`Negative: ${desc}`, async ({ page }) => {
    await page.goto('/login');
    await page.getByLabel('Username').fill(user);
    await page.getByLabel('Password').fill(pass);
    await page.getByRole('button', { name: 'Sign In' }).click();

    // Same generic message for all failures (anti-enumeration)
    await expect(page.getByText('Invalid credentials')).toBeVisible();
    // Must NOT reveal which field was wrong
    await expect(page.getByText('Username not found')).not.toBeVisible();
    await expect(page).toHaveURL(/\/login/);
  });
}
```

### What security cases should you test?

Security behaviors are central for a bank. Account lockout, injection resistance, and password masking protect customer accounts.

```typescript
// tests/login/security.spec.ts
test('Account locks after 5 failed attempts', async ({ page }) => {
  await page.goto('/login');
  for (let i = 0; i < 5; i++) {
    await page.getByLabel('Username').fill('rajesh@nationalbank.in');
    await page.getByLabel('Password').fill('wrong-' + i);
    await page.getByRole('button', { name: 'Sign In' }).click();
  }
  // 6th attempt with CORRECT password must still be refused
  await page.getByLabel('Username').fill('rajesh@nationalbank.in');
  await page.getByLabel('Password').fill(process.env.TEST_PASS!);
  await page.getByRole('button', { name: 'Sign In' }).click();
  await expect(page.getByText('Account locked')).toBeVisible();
});

test('SQL injection in username is rejected safely', async ({ page }) => {
  await page.goto('/login');
  await page.getByLabel('Username').fill("' OR 1=1 --");
  await page.getByLabel('Password').fill('anything');
  await page.getByRole('button', { name: 'Sign In' }).click();
  await expect(page.getByText('Invalid credentials')).toBeVisible();
  // Must NOT show database error or stack trace
  await expect(page.locator('body')).not.toContainText('SQL');
  await expect(page.locator('body')).not.toContainText('Exception');
});

test('XSS in username is escaped', async ({ page }) => {
  await page.goto('/login');
  await page.getByLabel('Username').fill('<script>alert(1)</script>');
  await page.getByLabel('Password').fill('anything');
  await page.getByRole('button', { name: 'Sign In' }).click();
  // No script execution, no alert dialog
  await expect(page.getByText('Invalid credentials')).toBeVisible();
});

test('Password field is masked', async ({ page }) => {
  await page.goto('/login');
  const passwordInput = page.getByLabel('Password');
  await expect(passwordInput).toHaveAttribute('type', 'password');
});
```

### What session management cases should you test?

Session behaviors include remember-me, session timeout, and logout. Each protects the user's authenticated state.

```typescript
// tests/login/session.spec.ts
test('Remember-me persists session across browser restart', async ({ browser }) => {
  const context = await browser.newContext();
  const page = await context.newPage();
  await page.goto('/login');
  await page.getByLabel('Username').fill(process.env.TEST_USER!);
  await page.getByLabel('Password').fill(process.env.TEST_PASS!);
  await page.getByLabel('Remember me').check();
  await page.getByRole('button', { name: 'Sign In' }).click();
  await expect(page).toHaveURL(/\/dashboard/);

  // Save cookies, close context, open new one with same cookies
  const cookies = await context.cookies();
  await context.close();
  const newContext = await browser.newContext();
  await newContext.addCookies(cookies);
  const newPage = await newContext.newPage();
  await newPage.goto('/dashboard');
  await expect(newPage).toHaveURL(/\/dashboard/);
  await newContext.close();
});

test('Logout invalidates server session', async ({ page }) => {
  // Login first
  await page.goto('/login');
  await page.getByLabel('Username').fill(process.env.TEST_USER!);
  await page.getByLabel('Password').fill(process.env.TEST_PASS!);
  await page.getByRole('button', { name: 'Sign In' }).click();
  await expect(page).toHaveURL(/\/dashboard/);

  // Logout
  await page.getByRole('button', { name: 'Logout' }).click();
  await expect(page).toHaveURL(/\/login/);

  // Back button must NOT reach dashboard
  await page.goBack();
  await expect(page).toHaveURL(/\/login/);
});
```

### What password reset cases should you test?

The password-reset flow must be secure: single-use links, time-limited, and no account enumeration.

```typescript
// tests/login/password-reset.spec.ts
test('Password reset link is single-use', async ({ page, request }) => {
  // Request a reset
  await page.goto('/forgot-password');
  await page.getByLabel('Email').fill('rajesh@nationalbank.in');
  await page.getByRole('button', { name: 'Send Reset Link' }).click();
  await expect(page.getByText('Check your email')).toBeVisible();

  // Simulate using the reset link (via API to get the token)
  const token = await getResetToken('rajesh@nationalbank.in');
  await page.goto(`/reset-password?token=${token}`);
  await page.getByLabel('New Password').fill('NewPass123!');
  await page.getByRole('button', { name: 'Reset' }).click();
  await expect(page.getByText('Password updated')).toBeVisible();

  // Same link again must be rejected
  await page.goto(`/reset-password?token=${token}`);
  await expect(page.getByText('Link expired')).toBeVisible();
});

test('Reset for non-existent email does not reveal account existence', async ({ page }) => {
  await page.goto('/forgot-password');
  await page.getByLabel('Email').fill('nobody@nationalbank.in');
  await page.getByRole('button', { name: 'Send Reset Link' }).click();
  // Same message whether the account exists or not
  await expect(page.getByText('Check your email')).toBeVisible();
});
```

### What accessibility and browser compatibility cases should you test?

Non-functional checks confirm the login page works for all users across all supported browsers.

```typescript
// tests/login/accessibility.spec.ts
import AxeBuilder from '@axe-core/playwright';

test('Login page passes accessibility audit', async ({ page }) => {
  await page.goto('/login');
  const results = await new AxeBuilder({ page }).analyze();
  expect(results.violations).toEqual([]);
});

test('Login form is keyboard navigable', async ({ page }) => {
  await page.goto('/login');
  await page.keyboard.press('Tab');
  await expect(page.getByLabel('Username')).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.getByLabel('Password')).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'Sign In' })).toBeFocused();
  await page.keyboard.press('Enter');
});
```

